formulas.expression:
IF(
    CONTAINS({!$Flow.FaultMessage}, 'FIELD_CUSTOM_VALIDATION_EXCEPTION:'),
    MID(
        {!$Flow.FaultMessage},
        FIND('FIELD_CUSTOM_VALIDATION_EXCEPTION:', {!$Flow.FaultMessage}) + 35,
        FIND('. You can look up', {!$Flow.FaultMessage}) - FIND('FIELD_CUSTOM_VALIDATION_EXCEPTION:', {!$Flow.FaultMessage}) - 35
    ),
    'Error Occurred: ' & {!$Flow.FaultMessage}
)
